import{_ as i,o as e,c as a,a2 as t}from"./chunks/framework.fsES6ZMC.js";const d=JSON.parse('{"title":"K8s for Senior Dev — 面向资深开发者的 Kubernetes 完整学习路径","description":"","frontmatter":{},"headers":[],"relativePath":"intro.md","filePath":"intro.md"}'),r={name:"intro.md"};function o(n,l,s,u,p,c){return e(),a("div",null,[...l[0]||(l[0]=[t('<h1 id="k8s-for-senior-dev-—-面向资深开发者的-kubernetes-完整学习路径" tabindex="-1">K8s for Senior Dev — 面向资深开发者的 Kubernetes 完整学习路径 <a class="header-anchor" href="#k8s-for-senior-dev-—-面向资深开发者的-kubernetes-完整学习路径" aria-label="Permalink to &quot;K8s for Senior Dev — 面向资深开发者的 Kubernetes 完整学习路径&quot;">​</a></h1><blockquote><p>定位：你已经写了十年 Java，懂 Docker、CI/CD、分布式系统，不需要再听&quot;容器是什么&quot;。 这份教程是一条 fast path：用你已有的工程直觉去映射 K8s 的设计，直奔资深开发者最容易踩的坑。</p><p>预计投入：精读 20-25 小时 + 动手 lab 15-20 小时（30 章完整版）。</p></blockquote><h2 id="读前自检" tabindex="-1">读前自检 <a class="header-anchor" href="#读前自检" aria-label="Permalink to &quot;读前自检&quot;">​</a></h2><p>以下问题全部&quot;是&quot;，直接开始；有&quot;否&quot;，先补对应章节（括号内）：</p><ul><li>我能说清 Docker 的 namespace/cgroup 分别隔离什么（第 2 章 2.1 有 5 分钟回顾）</li><li>我写过或维护过无状态服务的滚动发布（第 4 章）</li><li>我知道 CAP 定理、幂等、至少一次投递（第 10 章直接依赖）</li><li>我用命令行排过线上问题（ssh + grep log 级别即可）</li></ul><h2 id="全书结构-30-章" tabindex="-1">全书结构（30 章） <a class="header-anchor" href="#全书结构-30-章" aria-label="Permalink to &quot;全书结构（30 章）&quot;">​</a></h2><p><strong>第一部分：架构判断（为什么是 K8s）</strong></p><ul><li>第 1 章 为什么 K8s 赢了 — 一次架构史复盘，而不是技术赞美诗</li></ul><p><strong>第二部分：核心对象速通（每章一张心智图）</strong></p><ul><li>第 2 章 心智模型总装 — 控制面/数据面与声明式 API</li><li>第 3 章 Pod — 最小调度单元的真实语义</li><li>第 4 章 Deployment — 滚动发布的状态机</li><li>第 5 章 Service — 集群内的服务发现与负载均衡</li><li>第 6 章 Ingress 与 Gateway API — 七层入口</li><li>第 7 章 ConfigMap / Secret — 配置的分发与边界</li><li>第 8 章 存储 — PV / PVC / StorageClass 三层抽象</li></ul><p><strong>第三部分：资深开发者最容易踩的 10 个坑（第 9-11 章，按主题聚簇）</strong></p><ul><li>第 9 章 资源管理 — requests/limits/QoS/驱逐（坑 1-3）</li><li>第 10 章 优雅终止 — 探针/信号/PDB/滚动窗口（坑 4-7）</li><li>第 11 章 弹性伸缩 — HPA 抖动/VPA 重建/节点扩缩（坑 8-10）</li></ul><p><strong>第四部分：实战线</strong></p><ul><li>第 12 章 可观测性 — metrics / logs / tracing 三支柱落地</li><li>第 13 章 GPU 调度与 AI 应用部署 — 从 device plugin 到 vLLM</li><li>第 14 章 kind 实战 — 本地起集群、部署一个真实 AI 应用、全链路验证</li><li>第 15 章 排障手册 — kubectl 速查 + 20 个真实故障场景</li></ul><p><strong>第五部分：运营商级主题（第 16-27 章）</strong></p><ul><li>第 16 章 Gateway API 生产落地 — 分权模型/迁移/IngressNightmare</li><li>第 17 章 服务网格选型实战 — Sidecar/Ambient/eBPF 三路线与内存税</li><li>第 18 章 多集群与联邦 — 四个正当理由与 L1-L4 成本阶梯</li><li>第 19 章 GPU 调度深耕 — MIG/拓扑/gang 调度/DRA</li><li>第 20 章 安全加固 — 五层防线与加固体检 lab</li><li>第 21 章 PaC 成本治理 — OpenCost/右配/Spot/Karpenter 四杠杆</li><li>第 22 章 NetworkPolicy 与 CNI — 三定律与默认拒绝实操</li><li>第 23 章 Operator 与 CRD — kopf 40 行控制器与幂等性</li><li>第 24 章 GitOps 与渐进式交付 — ArgoCD/Rollouts/Secret 方案</li><li>第 25 章 etcd 与控制面 HA — 体检/备份恢复/故障指纹</li><li>第 26 章 大规模集群稳定性 — 五条物理定律与规模剖面</li><li>第 27 章 版本升级与灾备 — 升级清单/灾备重建计时</li></ul><p><strong>第六部分：冲刺线</strong></p><ul><li>第 28 章 公开事故复盘集 — 5 个可查证事件 + 10 个行业模式</li><li>第 29 章 毕业项目 — 生产级 AI 推理平台（9 项验收）</li><li>第 30 章 求职冲刺 — 面试地图 + 高频 20 题精写</li></ul><h2 id="约定" tabindex="-1">约定 <a class="header-anchor" href="#约定" aria-label="Permalink to &quot;约定&quot;">​</a></h2><ul><li>环境：macOS 或 Linux，Docker Desktop / OrbStack / Podman 均可；集群用 kind（第 14 章有完整安装步骤）。</li><li>版本基线：Kubernetes 1.30+。涉及版本差异的地方会显式标注（如 Gateway API 的 GA 状态、Sidecar 容器的正式版）。</li><li>每个 lab 都给出完整可复制命令，命令前标注预期耗时。</li><li>不确定/随环境而变的内容统一用 ⚠️ 标注。</li></ul><h2 id="建议节奏" tabindex="-1">建议节奏 <a class="header-anchor" href="#建议节奏" aria-label="Permalink to &quot;建议节奏&quot;">​</a></h2><ol><li>第 1 章精读（30 分钟）——先建立&quot;为什么&quot;，后面所有细节都有挂靠点。</li><li>第 2-8 章每章：读 20 分钟 + lab 15 分钟，一口气过完对象模型。</li><li>第 9-11 章是全书核心，慢读，每个坑都在自己集群里复现一遍。</li><li>第 14 章是总实战，前面所有 lab 的产出在这里汇成一个完整应用。</li><li>第 15 章当工具书用，先读&quot;排障总法&quot;，场景按需查。</li><li>第 16-27 章按职业方向选读：AI/平台岗重点 16/19/21/24；安全岗 20/22/25；通用资深 26/27。</li><li>第 29 章毕业项目作为 capstone，做完才算&quot;完整课&quot;闭环；第 30 章面试前两周开始背。</li></ol><h2 id="配套成品" tabindex="-1">配套成品 <a class="header-anchor" href="#配套成品" aria-label="Permalink to &quot;配套成品&quot;">​</a></h2><ul><li><a href="./landing.html">landing.html</a> — 课程介绍页（卖点/适合谁/试读）</li><li><a href="./index.html">index.html</a> — 30 章全课目录页（难度标注 + 一句话导读）</li><li><a href="./projects/">projects/</a> — 3 个 kind 集群真实可跑的实战项目（含 README + 部署/验收脚本）： <ol><li><a href="./projects/p1-ai-inference-hpa/README.html">带 HPA 的 AI 推理服务</a>（压测扩缩 + restricted 基线，6 项验收）</li><li><a href="./projects/p2-gitops-pipeline/README.html">GitOps 流水线</a>（ArgoCD + 集群内 Gitea，selfHeal 演示）</li><li><a href="./projects/p3-multi-tenant-governance/README.html">多租户 Namespace 治理</a>（配额/网络隔离/RBAC/准入四层）</li></ol></li><li><a href="./20-failures/">20-failures/</a> — 20 个故障卡片，与正文章节双向互链</li></ul>',24)])])}const f=i(r,[["render",o]]);export{d as __pageData,f as default};
